    const disc = event.target;
    if (!disc || !disc.classList || !disc.classList.contains("info-disc") || !disc.open) return;
    const pop = disc.querySelector(".info-pop");
    if (!pop) return;
    pop.style.transform = "";
    const rect = pop.getBoundingClientRect();
    const view = root.ownerDocument.defaultView;
    const viewport = view ? view.innerWidth : rect.right + MARGIN;
    let shift = 0;
    if (rect.right > viewport - MARGIN) shift = viewport - MARGIN - rect.right;
    /* Pulling it in from the right must never push the left edge off: a popover wider than
     * the viewport is clamped to the left margin and truncates on the right instead. */
    if (rect.left + shift < MARGIN) shift = MARGIN - rect.left;
    if (shift) pop.style.transform = `translateX(${Math.round(shift)}px)`;
